// Tracks which evidence each approval was granted on, so withdrawing one
// piece of evidence only puts the approvals that relied on it up for review.
export class ApprovalTracker {
  #evidence = new Set(); // currently valid evidence ids
  #approvals = new Map(); // approval id -> { basis: Set<evidence id>, status }

  addEvidence(id) {
    this.#evidence.add(id);
  }

  approve(id, basis) {
    const missing = [...basis].filter((e) => !this.#evidence.has(e));
    if (missing.length) throw new Error(`unknown or withdrawn evidence: ${missing.join(", ")}`);
    this.#approvals.set(id, { basis: new Set(basis), status: "approved" });
  }

  // Withdraw evidence; returns ids of approvals that now need reconsideration.
  withdraw(evidenceId) {
    this.#evidence.delete(evidenceId);
    const affected = [];
    for (const [id, a] of this.#approvals) {
      if (a.status === "approved" && a.basis.has(evidenceId)) {
        a.status = "reconsider";
        affected.push(id);
      }
    }
    return affected;
  }

  status(id) {
    const a = this.#approvals.get(id);
    if (!a) throw new Error(`unknown approval: ${id}`);
    return a.status;
  }
}
EOF
cat > approvals.test.mjs <<'EOF'
import test from "node:test";
import assert from "node:assert/strict";
import { ApprovalTracker } from "./approvals.mjs";

function setup() {
  const t = new ApprovalTracker();
  t.addEvidence("A");
  t.addEvidence("B");
  t.approve("one", ["A"]);
  t.approve("two", ["B"]);
  return t;
}

test("withdrawing evidence A reconsiders only approval one", () => {
  const t = setup();
  assert.deepEqual(t.withdraw("A"), ["one"]);
  assert.equal(t.status("one"), "reconsider");
  assert.equal(t.status("two"), "approved");
});

test("withdrawing evidence B reconsiders only approval two", () => {
  const t = setup();
  assert.deepEqual(t.withdraw("B"), ["two"]);
  assert.equal(t.status("one"), "approved");
});

test("shared evidence affects both approvals", () => {
  const t = new ApprovalTracker();
  t.addEvidence("A");
  t.approve("one", ["A"]);
  t.approve("two", ["A"]);
  assert.deepEqual(t.withdraw("A"), ["one", "two"]);
});

test("unrelated withdrawal changes nothing; cannot approve on withdrawn evidence", () => {
  const t = setup();
  assert.deepEqual(t.withdraw("Z"), []);
  t.withdraw("A");
  assert.throws(() => t.approve("three", ["A"]));
});
EOF
node --test 2>&1 | tail -12

